from pathlib import Path
p=Path("index.html")
s=p.read_text(encoding="utf-8")
logo="data:image/webp;base64,[... ELLIPSIZATION ...]"
old='.onlineBrand{text-align:center;margin-bottom:18px}.onlineBrand h1{margin:0;font-size:clamp(30px,6vw,52px);letter-spacing:1px}.onlineBeta'
new='.onlineBrand{text-align:center;margin-bottom:18px}.onlineBrandLogo{display:block;width:min(420px,82vw);max-height:250px;object-fit:contain;margin:0 auto 4px;filter:drop-shadow(0 8px 18px #0008)}.onlineBrandOnline{font-size:clamp(20px,4vw,32px);font-weight:900;letter-spacing:.12em;text-transform:uppercase;margin-top:-8px}.onlineBeta'
if old not in s: raise SystemExit("brand css not found")
s=s.replace(old,new,1)
old='<div class="onlineBrand"><h1>Tribu Le Jeu Online</h1><span class="onlineBeta">version bêta</span></div>'
new=f'<div class="onlineBrand"><img class="onlineBrandLogo" src="{logo}" alt="Tribu — Conquest of Myrmigate"><div class="onlineBrandOnline">Online</div><span class="onlineBeta">version bêta</span></div>'
if old not in s: raise SystemExit("brand html not found")
s=s.replace(old,new,1)
old="<select id=\"gameMode\" hidden><option value=\"1v3\">1v3</option><option value=\"1v4\">1v4</option><option value=\"2v3\">2v3</option><option value=\"3h\">3h</option>"
new="<select id=\"gameMode\" hidden><option value=\"1v3\">1v3</option><option value=\"1v4\">1v4</option><option value=\"2v3\">2v3</option><option value=\"3v2-online\">3v2-online</option><option value=\"3h\">3h</option>"
if old not in s: raise SystemExit("game mode select not found")
s=s.replace(old,new,1)
old="else if(mode==='2v3'){count=5}\n else if(mode==='3h'){count=3}"
new="else if(mode==='2v3'){count=5}\n else if(mode==='3v2-online'){count=5}\n else if(mode==='3h'){count=3}"
if old not in s: raise SystemExit("mode count not found")
s=s.replace(old,new,1)
old="if(mode==='2v3')G.players.forEach((pl,i)=>pl.bot=i>=2);"
new="if(mode==='2v3')G.players.forEach((pl,i)=>pl.bot=i>=2);\n if(mode==='3v2-online')G.players.forEach((pl,i)=>pl.bot=i>=3);"
if old not in s: raise SystemExit("bot assignment not found")
s=s.replace(old,new,1)
old="const label=mode==='2v3'?'2 joueurs + 3 bots — même support':"
new="const label=mode==='2v3'?'2 joueurs + 3 bots — même support':\n               mode==='3v2-online'?'3 joueurs + 2 bots — Online':"
if old not in s: raise SystemExit("badge label not found")
s=s.replace(old,new,1)
anchor="function onlineNotice(msg){$('lobbyNotice').textContent=msg}\n"
insert="""function onlineSeededRandom(seed){let x=(Number(seed)||1)>>>0;return ()=>{x+=0x6D2B79F5;let t=x;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296}}
function launchOnlineRoom(room){
 if(!room||room.seed===null||room.seed===undefined)return onlineError(new Error('Graine de partie absente. Attendez le redéploiement du serveur Render.'));
 onlineRoom=room;onlineSelectedMode=room.mode;
 const mode=room.mode==='2v3-online'?'2v3':room.mode;
 $('gameMode').value=mode;$('victoryMode').value=String(room.victoryPoints||3);
 $('start').classList.add('hidden');$('game').classList.remove('hidden');
 const nativeRandom=Math.random;Math.random=onlineSeededRandom(room.seed);try{init()}finally{Math.random=nativeRandom}
 room.players.forEach((pl,i)=>{if(G.players[i])G.players[i].name=pl.pseudo});
 G.online={code:room.code,seed:room.seed,mySocketId:onlineSocket&&onlineSocket.id,myPlayerIndex:room.players.findIndex(pl=>onlineSocket&&pl.id===onlineSocket.id),hostId:room.hostId};
 render();
}
"""
if anchor not in s: raise SystemExit("online notice anchor not found")
s=s.replace(anchor,anchor+insert,1)
old="socket.on('gameLaunched',room=>{onlineRoom=room;onlineNotice('Partie lancée. Synchronisation du moteur de jeu à venir à l’étape suivante.');$('onlineLaunch').disabled=true;$('onlineReady').disabled=true});"
new="socket.on('gameLaunched',room=>{onlineRoom=room;$('onlineLaunch').disabled=true;$('onlineReady').disabled=true;launchOnlineRoom(room)});"
if old not in s: raise SystemExit("gameLaunched handler not found")
s=s.replace(old,new,1)
s=s.replace('/* TRIBU Online beta — accueil et salons (étape 1, sans serveur réseau) */','/* TRIBU Online beta — salons temps réel + lancement commun */',1)
